/// Font helpers. Bundle the TTF/OTF files of these families in the app target
/// (Google Fonts, OFL); the woff2 files in fonts/ are for the web only.
public enum SCFont {
    public static func display(_ size: CGFloat, weight: Font.Weight = .regular) -> Font {
        Font.custom("Orbitron", size: size).weight(weight)
    }
    public static func ui(_ size: CGFloat, weight: Font.Weight = .regular) -> Font {
        Font.custom("Exo 2", size: size).weight(weight)
    }
    public static func mono(_ size: CGFloat, weight: Font.Weight = .regular) -> Font {
        Font.custom("Share Tech Mono", size: size).weight(weight)
    }
}
